// Gerenciador de Estado Reativo
class PlurixDataManager {
  constructor() {
    this.storageKey = 'plurix_procurement_dashboard_data_v4';
    this.data = this.loadData();
  }

  loadData() {
    try {
      if (typeof localStorage !== 'undefined') {
        const saved = localStorage.getItem(this.storageKey);
        if (saved) {
          const parsed = JSON.parse(saved);
          if (parsed && parsed.loaded && parsed.ytd && parsed.ytd.realizadoOpex > 0) {
            return parsed;
          }
        }
      }
    } catch (e) {
      console.warn('Erro ao carregar dados do LocalStorage, usando dados padrão:', e);
    }
    return JSON.parse(JSON.stringify(demoPlurixData));
  }

  saveData(newData) {
    try {
      this.data = newData;
      this.data.lastUpdated = new Date().toISOString().split('T')[0];
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem(this.storageKey, JSON.stringify(this.data));
      }
      return true;
    } catch (e) {
      console.error('Erro ao salvar dados:', e);
      return false;
    }
  }

  loadDemoData() {
    this.data = JSON.parse(JSON.stringify(demoPlurixData));
    this.saveData(this.data);
    return this.data;
  }

  resetToDefault() {
    if (typeof localStorage !== 'undefined') {
      localStorage.removeItem(this.storageKey);
    }
    this.data = JSON.parse(JSON.stringify(emptyPlurixData));
    return this.data;
  }

  exportJSON() {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(this.data, null, 2));
    const dlAnchorElem = document.createElement('a');
    dlAnchorElem.setAttribute("href", dataStr);
    dlAnchorElem.setAttribute("download", 'fechamento_plurix_' + (this.data.lastUpdated || 'vazio') + '.json');
    dlAnchorElem.click();
  }
}

// Instância global e variáveis seguras
if (typeof window !== 'undefined') {
  window.plurixStore = new PlurixDataManager();
  window.plurixData = window.plurixStore.data;
  var plurixData = window.plurixStore.data;
} else if (typeof module !== 'undefined') {
  module.exports = { emptyPlurixData, demoPlurixData, PlurixDataManager };
}
